// Independent control-only opponent suite. It observes public match state and
// uses the same buttons and cooldowns as a human. It never changes physics.
export function installHumanOpponent({side=0,style=0}) {
 const core=window.__BS2019_REQUIRE__(2).MainGameCore.instance;
 const players=[core.playersLeft[0],core.playersRight[0]],p=players[side],o=players[1-side],c=p.controller;
 const s=p.SIDE;let time=0,held=0,air=0,steal=0,had=false,faked=false,retreated=false,takeoff=0;
 c.update=function(dt){
  time+=dt;steal=Math.max(0,steal-dt);
  Object.assign(c,{currentMove:2,currentJump:false,currentJumpSkip:false,currentAction:false,currentDash:0,currentBlockOrPump:false,currentSuper:false});
  const gap=Math.abs(p.getX()-o.getX()),distance=s===1?p.getX():800-p.getX();
  if(p.withBall){
   if(!had){held=0;faked=false;retreated=false;}had=true;held+=dt;air=0;
   if(p.readyForSuper){c.currentSuper=true;return;}
   const three=style!==3&&distance>=450;
   if(!p.isGrounded){
    const start=s===1?p.pointOfThrow:800-p.pointOfThrow,target=three?Math.max(470,start-55):140;
    c.currentMove=distance>target+4?-s:2;
    if(p.canThrow&&p.getY()<=275&&(c.currentMove===2||!three))c.currentAction=true;
    return;
   }
   if(style===2&&!retreated&&held<.35&&gap<130&&distance<575){c.currentMove=s;if(p.readyForDash)c.currentDash=s;return;}retreated=true;
   const target=three?535:150;
   if(Math.abs(distance-target)>10){c.currentMove=distance>target?-s:s;if(!three&&distance>target+130&&p.readyForDash)c.currentDash=-s;return;}
   if(style===1&&!faked&&gap<160&&held>.12){c.currentBlockOrPump=true;faked=true;takeoff=held+.32;return;}
   if(style===1&&faked&&held<takeoff)return;
   c.currentJump=true;c.currentMove=three?-s:2;return;
  }
  had=false;held=0;
  if(o.withBall){
   const target=o.getX()+s*34+o.body.velocity.x*.08,dx=target-p.getX();c.currentMove=Math.abs(dx)>6?Math.sign(dx):2;
   air=o.isGrounded?0:air+dt;
   if(p.isGrounded&&!o.isGrounded&&air>=(style===2?.10:.05)&&o.body.velocity.y<-25&&gap<145)c.currentJump=true;
   else if(p.isGrounded&&o.isGrounded&&gap<48&&p.canAct&&steal===0){c.currentAction=true;steal=.7;}
   else if(p.isGrounded&&gap>190&&p.readyForDash)c.currentDash=Math.sign(dx);
   // One eager defender reacts to the visible pump animation, not hidden input.
   if(style===1&&p.isGrounded&&/pump/i.test(o.state||'')&&gap<110)c.currentJump=true;
  }else{
   air=0;const ball=core.ball,dx=ball.getX()+ball.body.velocity.x*.10-p.getX();c.currentMove=Math.abs(dx)>6?Math.sign(dx):2;
   if(p.isGrounded&&Math.abs(dx)<90&&ball.getY()<330&&ball.getY()>180&&ball.body.velocity.y>0)c.currentJump=true;
   else if(p.isGrounded&&Math.abs(dx)>190&&p.readyForDash)c.currentDash=Math.sign(dx);
  }
 };
}
